*,*::before,*::after{box-sizing:border-box;}
html,body{width:100%;}
body{margin:0;padding:4px 6px 10px;font-family:'Open Sans','Inter','Segoe UI',Arial,sans-serif;background:transparent;color:var(--appsmith-theme-textColor, #e2e8f0);}
.tabs{display:flex;gap:4px;border-bottom:1px solid var(--appsmith-theme-borderColor, #334155);margin-bottom:20px;}
.tab{padding:10px 18px;font-size:14px;font-weight:600;color:var(--appsmith-theme-textSecondaryColor, #94a3b8);cursor:pointer;border:1px solid transparent;border-bottom:none;border-radius:6px 6px 0 0;user-select:none;}
.tab:hover{color:var(--appsmith-theme-textColor, #e2e8f0);}
.tab.active{color:var(--dark-f1f5f9, var(--appsmith-theme-textStrongColor, #ffffff));background:var(--appsmith-theme-surfaceAltColor, #1e293b);border-color:var(--appsmith-theme-borderColor, #334155);}
.sect{margin-bottom:22px;}
.sect-title{font-size:15px;font-weight:700;color:var(--appsmith-theme-linkSoftColor, #93c5fd);margin-bottom:8px;}
.stbl{width:100%;border-collapse:collapse;background:var(--appsmith-theme-surfaceColor, #0f172a);border:1px solid var(--appsmith-theme-borderColor, #334155);border-radius:6px;overflow:hidden;}
.stbl td{padding:11px 16px;border-bottom:1px solid var(--appsmith-theme-borderColor, #334155);font-size:14px;}
.stbl tr:last-child td{border-bottom:none;}
.lbl{color:var(--appsmith-theme-textSecondaryColor, #94a3b8);width:340px;}
.val{color:var(--dark-f1f5f9, var(--appsmith-theme-textStrongColor, #ffffff));font-weight:600;}
.audit{width:30%;color:var(--appsmith-theme-textSoftColor, #cbd5e1);font-weight:400;}
.link{color:var(--appsmith-theme-linkColor, #60a5fa);text-decoration:underline;cursor:pointer;}
.ctbl{width:100%;border-collapse:collapse;background:var(--appsmith-theme-surfaceColor, #0f172a);border:1px solid var(--appsmith-theme-borderColor, #334155);border-radius:6px;overflow:hidden;font-size:14px;}
.ctbl th{text-align:left;padding:12px 16px;color:var(--appsmith-theme-textSoftColor, #cbd5e1);font-weight:700;border-bottom:1px solid var(--appsmith-theme-borderColor, #334155);}
.ctbl td{padding:12px 16px;color:var(--appsmith-theme-textColor, #e2e8f0);border-bottom:1px solid var(--appsmith-theme-borderSoftColor, #1e293b);}
.ctbl tr:last-child td{border-bottom:none;}
.idcell{color:var(--appsmith-theme-linkColor, #60a5fa);}
.empty{padding:24px;text-align:center;color:var(--appsmith-theme-textMutedColor, #64748b);font-style:italic;}

