/* Dark mode: restore the original dark shades (--dark-xxxxxx vars); light mode keeps the theme colours. */
(function(){var H=["4ade80", "f1f5f9"];function go(){var b=(getComputedStyle(document.body||document.documentElement).getPropertyValue('--appsmith-theme-backgroundColor')||'').trim().toLowerCase();if(!b)return false;if(!/^(#fff(fff)?|white|rgba?\(255, ?255, ?255(, ?1)?\))$/.test(b))H.forEach(function(x){document.documentElement.style.setProperty('--dark-'+x,'#'+x);});return true;}if(!go())window.addEventListener('load',go);})();

var TAB = "user";

function esc(s){ return (s==null||s==="") ? "—" : String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function row(label, valueHtml, audit){
  var auditCell = (audit === undefined) ? "<td class='audit'></td>" : "<td class='audit'>" + (audit || "Admin System") + "</td>";
  return "<tr><td class='lbl'>" + label + "</td><td class='val'>" + valueHtml + "</td>" + auditCell + "</tr>";
}

function section(title, rowsHtml){
  return "<div class='sect'><div class='sect-title'>" + title + "</div>" +
         "<table class='stbl'>" + rowsHtml + "</table></div>";
}

function userTab(detail){
  var d = (Array.isArray(detail) && detail[0]) || {};
  var pill = d.active
    ? "<span style='color:var(--dark-4ade80, var(--appsmith-theme-successColor, #34d399));'>&#9679; Active</span>"
    : "<span style='color:var(--appsmith-theme-dangerColor, #f87171);'>&#9679; Inactive</span>";
  var main = section("Main Information",
    row("ID", esc(d.id)) +
    row("First Name", esc(d.first_name), "Admin System") +
    row("Last Name", esc(d.last_name), "Admin System") +
    row("Email", esc(d.email)) +
    row("Phone number", esc(d.phone), "Admin System") +
    row("Notifications", (d.notification ? esc(d.notification) : "Email"), "Admin System") +
    row("Role", (d.role ? esc(d.role) : "Customer"), "Admin System"));
  var status = section("Status", row("User status", pill, "Admin System"));
  var reset = section("Reset Password",
    "<tr><td colspan='3' style='padding:12px 16px;'><span class='link'>Send reset password email</span></td></tr>");
  return main + status + reset;
}

function customersTab(customers){
  var rows = Array.isArray(customers) ? customers : [];
  var head = "<tr><th>ID</th><th>Name</th><th>User Role</th><th>Job Title</th><th>Locations</th></tr>";
  var body = rows.length
    ? rows.map(function(r){
        return "<tr><td class='idcell'>" + esc(r.id) + "</td><td>" + esc(r.name) +
               "</td><td>" + esc(r.user_role) + "</td><td>" + esc(r.job_title) +
               "</td><td>" + esc(r.locations) + "</td></tr>";
      }).join("")
    : "<tr><td colspan='5' class='empty'>No customers</td></tr>";
  return "<table class='ctbl'>" + head + body + "</table>";
}

function render(model){
  var m = model || {};
  var root = document.getElementById("root");
  if (!root) return;
  var tabs = "<div class='tabs'>" +
    "<div class='tab " + (TAB === "user" ? "active" : "") + "' data-tab='user'>User Info</div>" +
    "<div class='tab " + (TAB === "customers" ? "active" : "") + "' data-tab='customers'>Customers</div>" +
    "</div>";
  var content = (TAB === "customers") ? customersTab(m.customers) : userTab(m.detail);
  root.innerHTML = tabs + "<div class='body'>" + content + "</div>";
  var els = root.querySelectorAll(".tab");
  for (var i = 0; i < els.length; i++){
    els[i].addEventListener("click", function(){
      TAB = this.getAttribute("data-tab");
      render(appsmith.model);
    });
  }
}

appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(render); });

